        'sections' => [
            [
                'label' => 'Verse 1',
                'kind' => 'verse',
                'num' => 1,
                'lines' => [
                    'Abide with me: fast falls the eventide;',
                    'the darkness deepens — Lord, with me abide.',
                    'When other helpers fail and comforts flee,',
                    'help of the helpless, O abide with me.',
                ],
            ],
            [
                'label' => 'Verse 2',
                'kind' => 'verse',
                'num' => 2,
                'lines' => [
                    'Swift to its close ebbs out life\'s little',
                    'day; Earth\'s joys grow dim; its glories pass',
                    'away; Change and decay in all around I',
                    'see; O Thou who changest not, abide with me.',
                ],
            ],
            [
                'label' => 'Verse 3',
                'kind' => 'verse',
                'num' => 3,
                'lines' => [
                    'Not a brief glance I beg, a',
                    'passing word; But as Thou dwell\'st with',
                    'Thy disciples, Lord, Familiar, condescending, patient, free.',
                    'Come not to sojourn, but abide with me.',
                ],
            ],
            [
                'label' => 'Verse 4',
                'kind' => 'verse',
                'num' => 4,
                'lines' => [
                    'Come not in terrors, as the King of',
                    'kings, But kind and good, with healing in Thy wings,',
                    'Tears for all woes, a heart for every',
                    'plea? Come, Friend of sinners, and thus bide with me.',
                ],
            ],
            [
                'label' => 'Verse 5',
                'kind' => 'verse',
                'num' => 5,
                'lines' => [
                    'Thou on my head in early youth didst',
                    'smile; And, though rebellious and perverse meanwhile, Thou hast',
                    'not left me, oft as I left Thee,',
                    'On to the close, O Lord, abide with me.',
                ],
            ],
        ],
