            [
                'label' => 'Verse 2',
                'kind' => 'verse',
                'num' => 2,
                'lines' => [
                    '\'Tis mystery all: th\'Immortal dies: Who can explore His strange design? In',
                    'vain the firstborn seraph tries To sound the depths of love divine.',
                    '\'Tis mercy all! Let earth adore, Let angel minds inquire no more.',
                ],
